(()=>{"use strict";chrome.runtime.onMessageExternal.addListener((e,o,t)=>{if("SYNC_AUTH"===e.type){const o=e.token;return chrome.storage.local.set({authToken:o},()=>{console.log("Token synchronized successfully from Web App."),t({success:!0})}),!0}}),chrome.runtime.onMessage.addListener((e,o,t)=>{if("GET_AUTH_TOKEN"===e.type)return chrome.storage.local.get(["authToken"],e=>{t({token:e.authToken||null})}),!0})})();